/**
 * `src/generated/register.json` — the credit lines the site may print, copied
 * from the register at BUILD time and never typed (#375 A7, #377 D4 rule 1
 * "verbatim, German, whole" and rule 10 "register first, code second").
 *
 * Why a generated file and not an import: the Astro server bundle is built
 * with `ssr.noExternal: true`, so an `import { LICENCE_CATALOGUE } from
 * "@viafrei/ingest"` inside a component would bundle `pg`, `pino` and the
 * whole worker tree into the public site. The register is a handful of
 * strings; this script copies exactly those, and `test/register-copy.test.ts`
 * fails when the copy and the register disagree — so the JSON is a cache of
 * the register, never a second register.
 *
 * In 1.6 the tiles themselves come from `packages/digest` as HTML fragments
 * that already carry their credit lines (A3). This copy is for what the SHELL
 * prints: the Phase-0 preview tiles and the page-level duplicate list (D4
 * rule 9 — a duplicate, never the only carrier).
 *
 *   npx tsx packages/web/scripts/generate-register.ts        # writes the file
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { LICENCE_CATALOGUE, MTSK_CONSUMER_NOTE, MTSK_NOTE_SOURCE, licenceTextFor } from "@viafrei/ingest";

/**
 * The register ids the 1.6 tiles may cite (#375 tile table). An id outside
 * this list is not in the copy, so a tile cannot cite a source that has no
 * approved line (BAB offers, BahnPark: `attribution: null`, no tile).
 */
export const TILE_SOURCE_IDS = [
  "autobahn",
  "mobilithek_roadworks_bast",
  "mobilithek_nms_events",
  "mobilithek_afir_ecomovement",
  "mobilithek_afir_enbw_stat",
  "mobilithek_afir_tesla_dyn",
  "mobilithek_afir_vw_dyn",
  "mobilithek_truckpark_static_geonutzv",
  "db_fasta",
  "tankerkoenig",
  "delfi_rt_tu",
] as const;

export type RegisterCopy = {
  readonly _generated: string;
  /**
   * `licence`: the licence text the row's licence obliges a link to (CC BY 4.0
   * § 3(a)(1)(C), owner 2026-10-05), from the ONE map in `@viafrei/ingest`
   * (`licenceTextFor`, keyed by the row's label), or null when it owes none.
   */
  readonly sources: Readonly<Record<string, { readonly attribution: string; readonly url: string; readonly licence: { readonly name: string; readonly url: string } | null }>>;
  readonly mtskNote: string;
  readonly mtskNoteSource: string;
};

export function buildRegister(): RegisterCopy {
  const sources: Record<string, { attribution: string; url: string; licence: { name: string; url: string } | null }> = {};
  for (const id of TILE_SOURCE_IDS) {
    const facts = LICENCE_CATALOGUE[id];
    if (!facts) throw new Error(`generate-register: '${id}' is not in LICENCE_CATALOGUE`);
    if (facts.attribution === null || facts.attribution === undefined) {
      throw new Error(`generate-register: '${id}' has no approved attribution — a tile may not cite it (#377 rule 2)`);
    }
    if (!facts.url) throw new Error(`generate-register: '${id}' has no url — the linked form is the obligation (#377 D4 rule 2)`);
    const lt = licenceTextFor(facts.label);
    sources[id] = { attribution: facts.attribution, url: facts.url, licence: lt === null ? null : { name: lt.name, url: lt.url } };
  }
  return {
    _generated:
      "GENERATED by packages/web/scripts/generate-register.ts from @viafrei/ingest LICENCE_CATALOGUE — do not edit; test/register-copy.test.ts fails on drift",
    sources,
    mtskNote: MTSK_CONSUMER_NOTE,
    mtskNoteSource: MTSK_NOTE_SOURCE,
  };
}

const here = dirname(fileURLToPath(import.meta.url));
export const REGISTER_COPY_PATH = join(here, "..", "src", "generated", "register.json");

if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(REGISTER_COPY_PATH, `${JSON.stringify(buildRegister(), null, 2)}\n`);
  console.log(`wrote ${REGISTER_COPY_PATH} (${TILE_SOURCE_IDS.length} sources)`);
}
